-- A drive, not a feed: folders, files and the zero-copy path from a file to a post.
--
-- Every row here is keyed by `account_id` first, so the whole table is one account's
-- namespace and can be moved to another shard by that column alone without rewriting a
-- single query: each statement in `crates/store/src/drive.rs` takes `account_id` as its
-- first predicate. For the same reason every id is a UUIDv7 generated by the application
-- (`Uuid::now_v7`), not a sequence — a shard cannot hand out a global sequence, and a
-- time-ordered id keeps the b-tree append-only the way a ULID does.
CREATE TABLE drive_folder (
    account_id text        NOT NULL REFERENCES account (id) ON DELETE CASCADE,
    id         uuid        NOT NULL,
    parent_id  uuid,
    name       text        NOT NULL CHECK (name <> ''),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (account_id, id),
    -- The parent is in the same account, always: a folder tree cannot straddle two
    -- accounts, and a subtree cannot be re-parented onto someone else's folder.
    -- `ON DELETE CASCADE` on the self-reference is what makes "delete the folder" mean
    -- "delete the subtree" in one statement, at any depth.
    CONSTRAINT drive_folder_parent_fk
        FOREIGN KEY (account_id, parent_id) REFERENCES drive_folder (account_id, id)
        ON DELETE CASCADE
);

-- Listing a folder asks for its children; the parent is the second predicate after the
-- account, and the root listing is the same index with `parent_id IS NULL`.
CREATE INDEX drive_folder_parent_idx ON drive_folder (account_id, parent_id);

CREATE TABLE drive_object (
    account_id       text        NOT NULL REFERENCES account (id) ON DELETE CASCADE,
    id               uuid        NOT NULL,
    folder_id        uuid,
    filename         text        NOT NULL,
    mime_type        text        NOT NULL,
    byte_size        bigint      NOT NULL CHECK (byte_size >= 0),
    sha256           text        NOT NULL CHECK (sha256 ~ '^[0-9a-f]{64}$'),
    -- Who may fetch it. `unlisted_link` is shareable-by-URL without being enumerable;
    -- `public_federated` may leave the instance. The default is the closed one.
    visibility       text        NOT NULL DEFAULT 'private'
        CHECK (visibility IN ('private', 'unlisted_link', 'public_federated')),
    -- Whether the bytes are usable yet: an upload is a row before it is a file.
    processing_state text        NOT NULL DEFAULT 'pending'
        CHECK (processing_state IN ('pending', 'ready', 'failed')),
    created_at       timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (account_id, id),
    -- `folder_id IS NULL` is the root of the drive, so a file is never homeless.
    -- The subtree rule is the folder's: deleting a folder takes what was filed in it.
    CONSTRAINT drive_object_folder_fk
        FOREIGN KEY (account_id, folder_id) REFERENCES drive_folder (account_id, id)
        ON DELETE CASCADE
);

-- Dedupe: before storing an upload the caller asks whether this account already holds
-- these exact bytes, and this is the index that answers it.
CREATE INDEX drive_object_sha_idx ON drive_object (account_id, sha256);

-- Paging one folder, newest first — the drive's only list query.
CREATE INDEX drive_object_folder_idx ON drive_object (account_id, folder_id, created_at DESC);

-- The attachment remembers which drive object it came from.
--
-- There is deliberately **no foreign key**: a post outlives the file that was attached to
-- it. If this column referenced `drive_object`, deleting the file (or its folder) would
-- either cascade into a published post — silently removing a picture from someone's
-- timeline — or block the delete. Neither is acceptable, so the link is a plain uuid and
-- the drive never learns that a copy of its bytes is pinned in the social graph.
ALTER TABLE media_attachment ADD COLUMN stored_object_id uuid;
